-- ============================================================================
-- MFGPulse AI Test Suite: TC-05 WO/PO Lifecycle
-- ============================================================================
SELECT 'TC-05-01' AS TEST_ID, 'Valid WO types' AS TEST_NAME, 0 AS EXPECTED, COUNT_IF(WO_TYPE NOT IN ('emergency','corrective','preventive')) AS ACTUAL, CASE WHEN COUNT_IF(WO_TYPE NOT IN ('emergency','corrective','preventive'))=0 THEN 'PASS' ELSE 'FAIL' END AS STATUS FROM MFGPULSE_DB.RAW_IT.WORK_ORDERS;
SELECT 'TC-05-02' AS TEST_ID, 'Valid WO statuses' AS TEST_NAME, 0 AS EXPECTED, COUNT_IF(STATUS NOT IN ('open','in_progress','completed','cancelled')) AS ACTUAL, CASE WHEN COUNT_IF(STATUS NOT IN ('open','in_progress','completed','cancelled'))=0 THEN 'PASS' ELSE 'FAIL' END AS STATUS FROM MFGPULSE_DB.RAW_IT.WORK_ORDERS;
SELECT 'TC-05-03' AS TEST_ID, 'Completed have date' AS TEST_NAME, 0 AS EXPECTED, COUNT_IF(STATUS='completed' AND COMPLETED_DATE IS NULL) AS ACTUAL, CASE WHEN COUNT_IF(STATUS='completed' AND COMPLETED_DATE IS NULL)=0 THEN 'PASS' ELSE 'FAIL' END AS STATUS FROM MFGPULSE_DB.RAW_IT.WORK_ORDERS;
SELECT 'TC-05-04' AS TEST_ID, 'Valid ROOT_CAUSE values' AS TEST_NAME, 0 AS EXPECTED, COUNT_IF(STATUS='completed' AND ROOT_CAUSE_CONFIRMED IS NOT NULL AND ROOT_CAUSE_CONFIRMED NOT IN ('bearing_wear','thermal_degradation','imbalance','misalignment','electrical_fault','lubrication_failure','overload','other','unknown','normal','—')) AS ACTUAL, CASE WHEN COUNT_IF(STATUS='completed' AND ROOT_CAUSE_CONFIRMED IS NOT NULL AND ROOT_CAUSE_CONFIRMED NOT IN ('bearing_wear','thermal_degradation','imbalance','misalignment','electrical_fault','lubrication_failure','overload','other','unknown','normal','—'))=0 THEN 'PASS' ELSE 'FAIL' END AS STATUS FROM MFGPULSE_DB.RAW_IT.WORK_ORDERS;
SELECT 'TC-05-05' AS TEST_ID, 'PART_USED is boolean' AS TEST_NAME, 0 AS EXPECTED, COUNT_IF(PART_USED IS NOT NULL AND PART_USED NOT IN (TRUE, FALSE)) AS ACTUAL, CASE WHEN COUNT_IF(PART_USED IS NOT NULL AND PART_USED NOT IN (TRUE, FALSE))=0 THEN 'PASS' ELSE 'FAIL' END AS STATUS FROM MFGPULSE_DB.RAW_IT.WORK_ORDERS;
SELECT 'TC-05-06' AS TEST_ID, 'Valid PO statuses' AS TEST_NAME, 0 AS EXPECTED, COUNT_IF(STATUS NOT IN ('pending_approval','approved','cancelled','received','ordered','shipped')) AS ACTUAL, CASE WHEN COUNT_IF(STATUS NOT IN ('pending_approval','approved','cancelled','received','ordered','shipped'))=0 THEN 'PASS' ELSE 'FAIL' END AS STATUS FROM MFGPULSE_DB.RAW_IT.PURCHASE_ORDERS;
SELECT 'TC-05-07' AS TEST_ID, 'Alerts exist' AS TEST_NAME, 'TRUE' AS EXPECTED, CASE WHEN COUNT(*)>0 THEN 'TRUE' ELSE 'FALSE' END AS ACTUAL, CASE WHEN COUNT(*)>0 THEN 'PASS' ELSE 'FAIL' END AS STATUS FROM MFGPULSE_DB.ANALYTICS.ACTIVE_ALERTS WHERE SEVERITY IN ('WATCH','INFO');
SELECT 'TC-05-08' AS TEST_ID, 'OEE all assets' AS TEST_NAME, 10 AS EXPECTED, COUNT(DISTINCT ASSET_ID) AS ACTUAL, CASE WHEN COUNT(DISTINCT ASSET_ID)=10 THEN 'PASS' ELSE 'FAIL' END AS STATUS FROM MFGPULSE_DB.ANALYTICS.OEE_METRICS;
SELECT 'TC-05-09' AS TEST_ID, 'Rejected POs have reason' AS TEST_NAME, 0 AS EXPECTED, COUNT_IF(STATUS='cancelled' AND REJECTION_REASON IS NOT NULL AND LENGTH(TRIM(REJECTION_REASON))=0) AS ACTUAL, CASE WHEN COUNT_IF(STATUS='cancelled' AND REJECTION_REASON IS NOT NULL AND LENGTH(TRIM(REJECTION_REASON))=0)=0 THEN 'PASS' ELSE 'FAIL' END AS STATUS FROM MFGPULSE_DB.RAW_IT.PURCHASE_ORDERS;
SELECT 'TC-05-10' AS TEST_ID, 'PART_RESERVATIONS table exists' AS TEST_NAME, 1 AS EXPECTED, COUNT(*) AS ACTUAL, CASE WHEN COUNT(*)>=0 THEN 'PASS' ELSE 'FAIL' END AS STATUS FROM MFGPULSE_DB.INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA='RAW_IT' AND TABLE_NAME='PART_RESERVATIONS';
SELECT 'TC-05-11' AS TEST_ID, 'Active reservations have valid WO' AS TEST_NAME, 0 AS EXPECTED, (SELECT COUNT(*) FROM MFGPULSE_DB.RAW_IT.PART_RESERVATIONS pr LEFT JOIN MFGPULSE_DB.RAW_IT.WORK_ORDERS wo ON pr.WO_ID=wo.WO_ID WHERE pr.STATUS='active' AND wo.WO_ID IS NULL) AS ACTUAL, CASE WHEN (SELECT COUNT(*) FROM MFGPULSE_DB.RAW_IT.PART_RESERVATIONS pr LEFT JOIN MFGPULSE_DB.RAW_IT.WORK_ORDERS wo ON pr.WO_ID=wo.WO_ID WHERE pr.STATUS='active' AND wo.WO_ID IS NULL)=0 THEN 'PASS' ELSE 'FAIL' END AS STATUS;
